#pragma once
#include "Patch.hpp"
void fourEnvelopeChecks(){
 using namespace memorylab;
 // The contour generator is exercised against stage boundaries, not snapshots
 // generated by another copy of the same implementation.
 for(double sr:{44100.,48000.,96000.,192000.}){
  FilterEnvelope e;EnvelopeSettings shape{.01,.02,.01,.02,.25,.02};e.noteOn(shape);
  auto advance=[&](int count){double value=0;while(count-->0)value=e.tick(sr);return value;};
  check(advance(int(sr*.009))==0,"mod envelope ignored delay");
  check(advance(int(sr*.011))>.45,"mod envelope attack failed");
  check(advance(int(sr*.015))>.99,"mod envelope hold failed");
  check(std::abs(advance(int(sr*.04))-.25)<1e-6,"mod envelope sustain failed");
  e.noteOff(sr);check(advance(int(sr*.025))==0,"mod envelope release failed");
  e.noteOn({0,.1,0,0,1,.02});advance(int(sr*.025));e.noteOff(sr);
  check(advance(int(sr*.025))==0,"mod envelope early release stuck");
  e.noteOn({0,0,0,0,.7,0});check(std::abs(e.tick(sr)-.7)<1e-12,"zero-time contour failed");e.noteOff(sr);check(e.tick(sr)==0,"zero release failed");
 }
 auto render=[](double sr,int block,int mask,int route,bool inactive=false,bool sustain=false,bool editStages=false){
  auto synth=std::make_unique<Synth>();synth->prepare(sr);
  auto param=[&](Param p,double value){synth->dispatch({0,EventKind::Parameter,0,value,0,p});};
  param(Param::Drive,0);param(Param::Cutoff,750);param(Param::Q,.8);
  for(int n:{3,4}){
   const bool third=n==3,active=(mask&(third?1:2))!=0;
   param(third?Param::Env3Attack:Param::Env4Attack,third?150:700);
   param(third?Param::Env3Sustain:Param::Env4Sustain,.6);
   if(inactive){param(third?Param::Env3Delay:Param::Env4Delay,123);param(third?Param::Env3Release:Param::Env4Release,13);}
   if(active)param(third?(route==0?Param::Env3Pitch:Param::Env3Cutoff):(route==0?Param::Env4Pitch:Param::Env4Cutoff),route==0?200:2);
  }
  synth->dispatch({0,EventKind::NoteOn,60,.8});
  if(editStages){param(Param::Env3Attack,10000);param(Param::Env4Attack,10000);param(Param::Env3Sustain,0);param(Param::Env4Sustain,0);}
  std::vector<float>out(int(sr*1.5));
  for(int pos=0;pos<int(out.size());){
   if(pos==int(sr*.7)){if(sustain)synth->dispatch({0,EventKind::Sustain,0,1});synth->dispatch({0,EventKind::NoteOff,60});}
   if(sustain&&pos==int(sr*.9))synth->dispatch({0,EventKind::Sustain,0,0});
   int count=std::min(block,int(out.size())-pos);
   for(int boundary:{int(sr*.7),int(sr*.9)})if(boundary>pos)count=std::min(count,boundary-pos);
   check(synth->render(out.data()+pos,count),"envelope render failed");pos+=count;
  }
  for(float x:out)check(std::isfinite(x)&&std::abs(x)<1,"envelope audio nonfinite/headroom");
  check(synth->activeVoices()==0,"modulation tail kept voice alive");return out;
 };
 for(double sr:{44100.,48000.,96000.,192000.})for(int route:{0,1}){
  const auto base=render(sr,127,0,route);
  check(base==render(sr,127,0,route,true),"inactive contour changed audio");
  for(int mask:{1,2,3}){
   auto out=render(sr,127,mask,route);check(out!=base,"new envelope route silent");
   check(out==render(sr,512,mask,route),"envelope block partition mismatch");
   check(out==render(sr,127,mask,route,false,false,true),"active envelope stage settings did not latch");
  }
  check(render(sr,127,3,route)!=render(sr,127,1,route),"envelope 4 contribution missing");
  check(render(sr,127,3,route)!=render(sr,127,2,route),"envelope 3 contribution missing");
  render(sr,127,3,route,false,true);
 }
 auto stolen=std::make_unique<Synth>();stolen->prepare(48000);
 stolen->dispatch({0,EventKind::Parameter,0,500,0,Param::Env3Pitch});
 for(int note=48;note<68;++note)stolen->dispatch({0,EventKind::NoteOn,note,.8});
 check(stolen->activeVoices()==8,"mod envelopes changed voice allocation");
 std::vector<float>tail(48000);stolen->dispatch({0,EventKind::AllSoundOff});stolen->render(tail.data(),tail.size());
 check(std::all_of(tail.begin(),tail.end(),[](float x){return x==0;}),"modulation state leaked after all sound off");
 auto p=std::make_unique<MemoryLabProcessor>();
 check(p->getParameters().size()==103,"four envelope parameter count");
 set(*p,"env3Pitch",250);set(*p,"env4Cutoff",1.25f);set(*p,"env4Attack",1250);
 const auto encoded=patch::encode(*p);auto xml=juce::parseXML(encoded);xml->setAttribute("schemaVersion",10);
 auto added=[](const juce::String&id){return id.startsWith("env3")||id.startsWith("env4")||id=="lfoAmp"||id=="lfo2Amp"||id=="lfo3Amp"||id=="lfo4Amp"||id=="ampPitch"||id=="fltPitch"||id=="env3Pwm"||id=="env4Pwm"||id=="osc1PulseLevel"||id=="osc2SawLevel"||id=="osc1Width";};
 for(int i=xml->getNumChildElements()-1;i>=0;--i)if(added(xml->getChildElement(i)->getStringAttribute("id")))xml->removeChildElement(xml->getChildElement(i),true);
 check(patch::apply(*p,xml->toString()).wasOk(),"schema 10 migration failed");
 check(p->state.getRawParameterValue("env3Pitch")->load()==0&&p->state.getRawParameterValue("env4Cutoff")->load()==0,"old patch retained new routes");
 check(patch::apply(*p,encoded).wasOk(),"new envelope patch recall failed");
 check(p->state.getRawParameterValue("env3Pitch")->load()==250&&p->state.getRawParameterValue("env4Attack")->load()==1250,"new envelope values not recalled");
 juce::MemoryBlock state;p->getStateInformation(state);auto restored=std::make_unique<MemoryLabProcessor>();restored->setStateInformation(state.getData(),int(state.getSize()));
 check(restored->state.getRawParameterValue("env4Cutoff")->load()==1.25f,"new envelope host recall failed");
 auto old=p->state.copyState();for(int i=old.getNumChildren()-1;i>=0;--i)if(added(old.getChild(i).getProperty("id").toString()))old.removeChild(i,nullptr);
 auto oldXml=old.createXml();juce::AudioProcessor::copyXmlToBinary(*oldXml,state);p->setStateInformation(state.getData(),int(state.getSize()));check(p->state.getRawParameterValue("env3Pitch")->load()==0,"old host retained new contour depth");
 auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());
 for(int source:{3,4}){auto*tab=dynamic_cast<juce::Button*>(find(*editor,"env"+juce::String(source)+"Page"));check(tab&&bool(tab->onClick),"envelope page missing");tab->onClick();for(const char*stage:{"Delay","Attack","Hold","Decay","Sustain","Release","Pitch","Cutoff"})check(find(*editor,"env"+juce::String(source)+stage),"envelope editor binding missing");}
 std::cout<<"PASS four envelopes: stage/early-release/zero-time boundaries, independent pitch/filter routes, combined sources, four rates, block parity, sustain/release, inactive isolation, old/new patch and host recall, editor bindings\n";
}
